CREATE TABLE "public"."invoices" (
  "invoice_id"       bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "invoice_number"   text,
  "job_id"           bigint                   NOT NULL,
  "date_entered"     date                     DEFAULT CURRENT_DATE,
  "date_due"         date,
  "paid_at"          timestamp with time zone,
  "no_charge"        boolean                  DEFAULT false,
  "comments"         text,
  "created_at"       timestamp with time zone DEFAULT now(),
  "updated_at"       timestamp with time zone DEFAULT now(),
  "is_creditmemo"    boolean                  DEFAULT false,
  "service_order_id" bigint,
  CONSTRAINT "invoices_pkey" PRIMARY KEY (invoice_id),
  CONSTRAINT "invoices_job_id_fkey" FOREIGN KEY (job_id) REFERENCES public.jobs(id) ON DELETE CASCADE,
  CONSTRAINT "invoices_service_order_id_fkey" FOREIGN KEY (service_order_id) REFERENCES public.service_orders(service_order_id)
);

ALTER TABLE "public"."invoices"
  ENABLE ROW LEVEL SECURITY;

CREATE TRIGGER set_updated_at
  BEFORE UPDATE ON public.invoices
  FOR EACH ROW
  EXECUTE FUNCTION public.handle_updated_at();

CREATE POLICY "Enable delete for admin only" ON "public"."invoices"
  FOR DELETE
  TO PUBLIC
  USING ((lower(public.clerk_user_role()) = ANY (ARRAY['admin'::text, 'reception'::text])));

CREATE POLICY "Enable insert for invoice editors" ON "public"."invoices"
  FOR INSERT
  TO PUBLIC
  WITH CHECK ((public.clerk_user_role() = ANY (ARRAY['admin'::text, 'reception'::text, 'service'::text])));

CREATE POLICY "Enable read access for authenticated users" ON "public"."invoices"
  FOR SELECT
  TO PUBLIC
  USING ((auth.role() = 'authenticated'::text));

CREATE POLICY "Enable update for invoice editors" ON "public"."invoices"
  FOR UPDATE
  TO PUBLIC
  USING ((public.clerk_user_role() = ANY (ARRAY['admin'::text, 'reception'::text, 'service'::text])));

REVOKE ALL ON SEQUENCE "public"."invoices_invoice_id_seq" FROM "anon";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."invoices_invoice_id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."invoices_invoice_id_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."invoices_invoice_id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."invoices_invoice_id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."invoices_invoice_id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."invoices_invoice_id_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."invoices_invoice_id_seq" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."invoices" TO "anon", "authenticated";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."invoices" TO "service_role";

REVOKE ALL ON TABLE "public"."invoices" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."invoices" TO "postgres";
